//! Federated continual context API/protocol adapter.
//!
//! Atlas feature: `AFA-brain-P03-F24`. The adapter emits an aggregate-only,
//! locality-preserving federation receipt; transport and institution-local data
//! access remain application-owned.

use bioprism_foundation::{AutonomyTier, CapabilityManifest, Determinism, Effect, EvidenceReference, EvidenceState, ResearchSurface, TypedPort, TypedResearchArtifact, PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID: &str = "AFA-brain-P03-F24";
pub const CONTRACT_VERSION: &str = "brain-federated-context-protocol-adapter/1.0";
pub const PROTOCOL_VERSION: &str = "aurora-research-context-federated/1.0";
pub const ROUTE: &str = "/v1/research/context/federated/compile";
pub const METHOD: &str = "POST";
pub const RESPONSE_SCHEMA: &str = "FederatedContextProtocolResponse1@1";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FederatedContextProtocolPeer { pub institution_id: String, pub endpoint: String, pub semantic_profile: String, pub context_digest: ContentHash, pub section_digest: ContentHash, pub replay_identity: ContentHash, pub state: EvidenceState, pub signed_approval: bool, pub raw_data_local: bool, pub aggregate_only: bool, pub boundary: String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FederatedContextProtocolRequest { pub request_id: String, pub federation_id: String, pub purpose: String, pub scope: String, pub goal: String, pub semantic_profile: String, pub peers: Vec<FederatedContextProtocolPeer>, pub minimum_quorum: u16, pub protocol_version: String, pub method: String, pub route: String, pub content_type: String, pub idempotency_key: String, pub response_schema: String, pub replay_identity: ContentHash, pub policy_allow: bool, pub protected_closure: bool, pub signer_valid: bool, pub raw_data_local: bool, pub aggregate_only: bool, pub boundary: String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FederatedContextProtocolReceipt { pub schema_version: String, pub contract_version: String, pub feature_id: String, pub request_id: String, pub federation_id: String, pub purpose: String, pub scope: String, pub goal: String, pub semantic_profile: String, pub protocol_version: String, pub method: String, pub route: String, pub content_type: String, pub idempotency_key: String, pub response_schema: String, pub status_code: u16, pub disposition: String, pub institution_order: Vec<String>, pub endpoint_order: Vec<String>, pub candidate_order: Vec<String>, pub admitted_order: Vec<String>, pub blocked_order: Vec<String>, pub unknown_order: Vec<String>, pub aggregate_order: Vec<ContentHash>, pub minimum_quorum: u16, pub quorum: u16, pub checkpoint_seq: u64, pub envelope_digest: ContentHash, pub context_digest: ContentHash, pub section_digest: ContentHash, pub request_digest: ContentHash, pub response_digest: ContentHash, pub replay_identity: ContentHash, pub omissions: Vec<String>, pub uncertainty: Vec<String>, pub negative_evidence: Vec<String>, pub effect_receipts: Vec<String>, pub artifact: TypedResearchArtifact, pub raw_data_local: bool, pub aggregate_only: bool, pub boundary: String }
#[derive(Debug, Error, PartialEq, Eq)]
pub enum FederatedContextProtocolError { #[error("invalid federated context protocol request: {0}")] Invalid(String), #[error("federated context protocol artifact failed: {0}")] Artifact(String) }

impl FederatedContextProtocolReceipt {
    pub fn validate(&self) -> Result<(), FederatedContextProtocolError> {
        if self.schema_version != RESEARCH_CONTRACT_SCHEMA_VERSION || self.contract_version != CONTRACT_VERSION || self.feature_id != FEATURE_ID || self.protocol_version != PROTOCOL_VERSION || self.method != METHOD || self.route != ROUTE || self.response_schema != RESPONSE_SCHEMA || self.boundary != PRECLINICAL_BOUNDARY || self.request_id.trim().is_empty() || self.federation_id.trim().is_empty() || self.purpose.trim().is_empty() || self.scope.trim().is_empty() || self.goal.trim().is_empty() || self.semantic_profile.trim().is_empty() || self.institution_order.len() < 2 || self.candidate_order.is_empty() || self.minimum_quorum == 0 || self.quorum != self.admitted_order.len() as u16 || self.quorum > self.candidate_order.len() as u16 || self.effect_receipts.is_empty() { return Err(FederatedContextProtocolError::Invalid("federated context protocol identity, quorum, locality, or effects are incomplete".into())); }
        for values in [&self.institution_order, &self.endpoint_order, &self.candidate_order, &self.admitted_order, &self.blocked_order, &self.unknown_order, &self.omissions, &self.uncertainty, &self.negative_evidence, &self.effect_receipts] { if values.windows(2).any(|p| p[0] >= p[1]) { return Err(FederatedContextProtocolError::Invalid("federated context protocol ordering is not canonical".into())); } }
        let classified = self.admitted_order.iter().chain(self.blocked_order.iter()).chain(self.unknown_order.iter()).cloned().collect::<BTreeSet<_>>(); if classified.len() != self.candidate_order.len() || classified.iter().any(|v| !self.candidate_order.contains(v)) { return Err(FederatedContextProtocolError::Invalid("federated context protocol states do not partition candidates".into())); }
        if !matches!(self.status_code, 200 | 202 | 206 | 403 | 422) || !matches!(self.disposition.as_str(), "ready" | "partial" | "unknown" | "blocked") { return Err(FederatedContextProtocolError::Invalid("federated context protocol status or disposition is invalid".into())); }
        for digest in [&self.envelope_digest, &self.context_digest, &self.section_digest, &self.request_digest, &self.response_digest, &self.replay_identity] { if digest.as_str().len() != 64 { return Err(FederatedContextProtocolError::Invalid("federated context protocol digest is invalid".into())); } }
        if self.aggregate_order.windows(2).any(|p| p[0].as_str() >= p[1].as_str()) || self.aggregate_order.len() > self.admitted_order.len() { return Err(FederatedContextProtocolError::Invalid("federated aggregate order is not canonical".into())); }
        if self.effect_receipts.iter().any(|e| !e.starts_with("protocol:federated-context-response:") && e != "block:unsafe-release") { return Err(FederatedContextProtocolError::Invalid("federated context protocol effect is outside the governed response gate".into())); }
        if !self.raw_data_local && (self.disposition != "blocked" || !self.omissions.iter().any(|v| v == "protocol:raw-data-locality-failed")) { return Err(FederatedContextProtocolError::Invalid("raw-data locality failure must remain blocked and explicit".into())); }
        self.artifact.validate_metadata().map_err(|e| FederatedContextProtocolError::Artifact(e.to_string()))
    }
    pub fn digest(&self) -> Result<ContentHash, FederatedContextProtocolError> { self.validate()?; let value = serde_json::to_value(self).map_err(|e| FederatedContextProtocolError::Artifact(e.to_string()))?; ContentHash::of_value(&value).map_err(|e| FederatedContextProtocolError::Artifact(e.to_string())) }
}

pub fn federated_context_protocol_manifest() -> CapabilityManifest { CapabilityManifest { schema_version: RESEARCH_CONTRACT_SCHEMA_VERSION.into(), capability_id: FEATURE_ID.into(), version: CONTRACT_VERSION.into(), owner_crate: "brain".into(), consumers: ["federated context gateway".into(), "research consortium operator".into(), "research SDK".into()].into(), behavior: "maps institution-local context attestations to an aggregate-only, quorum-aware federated protocol receipt".into(), value: "enables continual multi-institution context compilation without moving raw experimental data or hiding federation omissions".into(), inputs: vec![TypedPort { name: "federated_context_protocol_request".into(), schema: "FederatedContextProtocolRequest1@1".into(), required: true }], outputs: vec![TypedPort { name: "federated_context_protocol_response".into(), schema: RESPONSE_SCHEMA.into(), required: true }], effects: [Effect::ReadLocalData, Effect::ExecuteLocalComputation, Effect::WriteLocalArtifact, Effect::FederationExport].into(), permissions: ["protocol:federated-context-response".into(), "federation:aggregate-only".into()].into(), determinism: Determinism::ByteStable, evidence: vec![EvidenceReference { source_id: "w3c-prov-o".into(), state: EvidenceState::Supported, locator: Some("https://www.w3.org/TR/prov-o/".into()) }], authority_requirements: Vec::new(), autonomy_tier: AutonomyTier::A2, surfaces: [ResearchSurface::Ui, ResearchSurface::Api, ResearchSurface::Sdk, ResearchSurface::Cli, ResearchSurface::McpTool, ResearchSurface::Protocol, ResearchSurface::Policy, ResearchSurface::Operator].into(), boundary: PRECLINICAL_BOUNDARY.into() } }

pub fn serve_federated_context_protocol(request: &FederatedContextProtocolRequest) -> Result<FederatedContextProtocolReceipt, FederatedContextProtocolError> {
    if request.protocol_version != PROTOCOL_VERSION || request.method != METHOD || request.route != ROUTE || request.content_type != "application/json" || request.response_schema != RESPONSE_SCHEMA || request.request_id.trim().is_empty() || request.federation_id.trim().is_empty() || request.purpose.trim().is_empty() || request.scope.trim().is_empty() || request.goal.trim().is_empty() || request.semantic_profile.trim().is_empty() || request.peers.len() < 2 || request.minimum_quorum == 0 || request.minimum_quorum as usize > request.peers.len() || request.idempotency_key.trim().is_empty() || request.replay_identity.as_str().len() != 64 || request.boundary != PRECLINICAL_BOUNDARY { return Err(FederatedContextProtocolError::Invalid("federated context protocol identity, route, quorum, replay, or boundary is invalid".into())); }
    let mut peers = request.peers.clone(); peers.sort_by(|a, b| a.institution_id.cmp(&b.institution_id)); let candidate = peers.iter().map(|p| p.institution_id.clone()).collect::<Vec<_>>(); if candidate.windows(2).any(|p| p[0] == p[1]) || candidate.iter().any(|v| v.trim().is_empty()) { return Err(FederatedContextProtocolError::Invalid("federated institution identifiers must be unique and non-empty".into())); }
    let mut admitted = BTreeSet::new(); let mut blocked = BTreeSet::new(); let mut unknown = BTreeSet::new(); let mut aggregate = BTreeSet::new(); let mut omissions = BTreeSet::new(); let mut uncertainty = BTreeSet::new(); let mut negative = BTreeSet::new(); let open = request.policy_allow && request.protected_closure && request.signer_valid && request.raw_data_local && request.aggregate_only;
    for peer in &peers { if !open || !peer.signed_approval || !peer.raw_data_local || !peer.aggregate_only || peer.boundary != PRECLINICAL_BOUNDARY { blocked.insert(peer.institution_id.clone()); omissions.insert(format!("institution:{}:policy-approval-locality-blocked", peer.institution_id)); } else if peer.semantic_profile != request.semantic_profile { blocked.insert(peer.institution_id.clone()); negative.insert(format!("institution:{}:semantic-profile-mismatch", peer.institution_id)); } else if peer.replay_identity != request.replay_identity { unknown.insert(peer.institution_id.clone()); uncertainty.insert(format!("institution:{}:replay-mismatch", peer.institution_id)); } else if matches!(peer.state, EvidenceState::Unknown | EvidenceState::Speculative) { unknown.insert(peer.institution_id.clone()); uncertainty.insert(format!("institution:{}:evidence-uncertain", peer.institution_id)); } else if matches!(peer.state, EvidenceState::Contradicted) { blocked.insert(peer.institution_id.clone()); negative.insert(format!("institution:{}:contradicted", peer.institution_id)); } else { admitted.insert(peer.institution_id.clone()); aggregate.insert(peer.context_digest.clone()); } }
    let disposition = if !open { "blocked" } else if admitted.len() == candidate.len() && admitted.len() >= request.minimum_quorum as usize { "ready" } else if !unknown.is_empty() && admitted.len() < request.minimum_quorum as usize { "unknown" } else if admitted.len() >= request.minimum_quorum as usize { "partial" } else { "blocked" }; let status = if !open { 403 } else if disposition == "ready" { 200 } else if disposition == "partial" { 206 } else if disposition == "unknown" { 202 } else { 422 };
    if !request.policy_allow { omissions.insert("protocol:policy-denied".into()); } if !request.protected_closure { omissions.insert("protocol:protected-closure-incomplete".into()); } if !request.signer_valid { omissions.insert("protocol:signer-invalid".into()); } if !request.raw_data_local { omissions.insert("protocol:raw-data-locality-failed".into()); } if !request.aggregate_only { omissions.insert("protocol:aggregate-only-required".into()); }
    let institution_order = candidate.clone(); let endpoint_order = peers.iter().map(|p| p.endpoint.clone()).collect::<Vec<_>>(); let mut aggregate_order = aggregate.into_iter().collect::<Vec<_>>(); aggregate_order.sort_by(|a, b| a.as_str().cmp(b.as_str())); let quorum = admitted.len() as u16; let checkpoint_seq = peers.len() as u64; let envelope_digest = ContentHash::of_value(&json!({"federation_id":request.federation_id,"purpose":request.purpose,"semantic_profile":request.semantic_profile,"candidate_order":candidate,"aggregate_order":aggregate_order,"replay_identity":request.replay_identity,"aggregate_only":request.aggregate_only})).map_err(|e| FederatedContextProtocolError::Artifact(e.to_string()))?; let context_digest = ContentHash::of_value(&json!({"scope":request.scope,"envelope_digest":envelope_digest,"quorum":quorum})).map_err(|e| FederatedContextProtocolError::Artifact(e.to_string()))?; let section_digest = ContentHash::of_value(&json!({"goal":request.goal,"context_digest":context_digest,"admitted_order":admitted})).map_err(|e| FederatedContextProtocolError::Artifact(e.to_string()))?; let request_digest = ContentHash::of_value(&serde_json::to_value(request).map_err(|e| FederatedContextProtocolError::Artifact(e.to_string()))?).map_err(|e| FederatedContextProtocolError::Artifact(e.to_string()))?; let response_digest = ContentHash::of_value(&json!({"protocol_version":PROTOCOL_VERSION,"route":ROUTE,"request_id":request.request_id,"status_code":status,"disposition":disposition,"envelope_digest":envelope_digest,"replay_identity":request.replay_identity})).map_err(|e| FederatedContextProtocolError::Artifact(e.to_string()))?; let payload = json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":request.request_id,"federation_id":request.federation_id,"status_code":status,"disposition":disposition,"envelope_digest":envelope_digest,"context_digest":context_digest,"section_digest":section_digest,"replay_identity":request.replay_identity,"raw_data_local":request.raw_data_local,"aggregate_only":request.aggregate_only,"boundary":PRECLINICAL_BOUNDARY}); let artifact = TypedResearchArtifact::from_payload(format!("brain-federated-context-protocol:{}", request.request_id), "application/vnd.aurora.federated-context-protocol-response+json", &payload, Vec::new(), Vec::new()).map_err(|e| FederatedContextProtocolError::Artifact(e.to_string()))?; let receipt = FederatedContextProtocolReceipt { schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(), contract_version:CONTRACT_VERSION.into(), feature_id:FEATURE_ID.into(), request_id:request.request_id.clone(), federation_id:request.federation_id.clone(), purpose:request.purpose.clone(), scope:request.scope.clone(), goal:request.goal.clone(), semantic_profile:request.semantic_profile.clone(), protocol_version:PROTOCOL_VERSION.into(), method:METHOD.into(), route:ROUTE.into(), content_type:"application/json".into(), idempotency_key:request.idempotency_key.clone(), response_schema:RESPONSE_SCHEMA.into(), status_code:status, disposition:disposition.into(), institution_order, endpoint_order, candidate_order:candidate, admitted_order:admitted.into_iter().collect(), blocked_order:blocked.into_iter().collect(), unknown_order:unknown.into_iter().collect(), aggregate_order, minimum_quorum:request.minimum_quorum, quorum, checkpoint_seq, envelope_digest, context_digest, section_digest, request_digest, response_digest, replay_identity:request.replay_identity.clone(), omissions:omissions.into_iter().collect(), uncertainty:uncertainty.into_iter().collect(), negative_evidence:negative.into_iter().collect(), effect_receipts:if disposition != "blocked" { vec![format!("protocol:federated-context-response:{}", request.idempotency_key)] } else { vec!["block:unsafe-release".into()] }, artifact, raw_data_local:request.raw_data_local, aggregate_only:request.aggregate_only, boundary:PRECLINICAL_BOUNDARY.into() }; receipt.validate()?; Ok(receipt)
}

#[cfg(test)] mod tests { use super::*; fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())} fn request(state:EvidenceState)->FederatedContextProtocolRequest { let replay=h("federated-context-replay"); let peers=vec!["site:a","site:b"].into_iter().map(|institution_id| FederatedContextProtocolPeer{institution_id:institution_id.into(),endpoint:format!("https://{institution_id}.local/context"),semantic_profile:"profile:v1".into(),context_digest:replay.clone(),section_digest:replay.clone(),replay_identity:replay.clone(),state:state.clone(),signed_approval:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()}).collect(); FederatedContextProtocolRequest{request_id:"request:federated-context".into(),federation_id:"federation:preclinical".into(),purpose:"aggregate context".into(),scope:"preclinical:organoid".into(),goal:"compile federated context".into(),semantic_profile:"profile:v1".into(),peers,minimum_quorum:2,protocol_version:PROTOCOL_VERSION.into(),method:METHOD.into(),route:ROUTE.into(),content_type:"application/json".into(),idempotency_key:"idem:federated-context".into(),response_schema:RESPONSE_SCHEMA.into(),replay_identity:replay,policy_allow:true,protected_closure:true,signer_valid:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()} } #[test] fn manifest_is_a2_aggregate_only(){assert_eq!(federated_context_protocol_manifest().autonomy_tier,AutonomyTier::A2)} #[test] fn quorum_returns_200(){assert_eq!(serve_federated_context_protocol(&request(EvidenceState::Supported)).unwrap().status_code,200)} #[test] fn unknown_peer_returns_202(){assert_eq!(serve_federated_context_protocol(&request(EvidenceState::Unknown)).unwrap().status_code,202)} #[test] fn aggregate_gate_returns_403(){let mut x=request(EvidenceState::Supported);x.aggregate_only=false;assert_eq!(serve_federated_context_protocol(&x).unwrap().status_code,403)} #[test] fn semantic_mismatch_is_negative(){let mut x=request(EvidenceState::Supported);x.peers[0].semantic_profile="profile:other".into();let r=serve_federated_context_protocol(&x).unwrap();assert!(r.negative_evidence.iter().any(|v|v.contains("semantic-profile-mismatch")))} #[test] fn digest_is_stable(){let r=serve_federated_context_protocol(&request(EvidenceState::Supported)).unwrap();assert_eq!(r.digest().unwrap(),r.digest().unwrap())} }
